-- Eldervale exploration, part 3: treasure-hunt clue steps (48) and reward casket tables.
-- Generated by scripts/build-explore-sql.mjs from explore-data.js. Do not edit by hand.
-- APPLY AFTER db/explore-2-content.sql. Idempotent; rows saved from the Exploration console (owner_edited) are kept.
begin;
set local lock_timeout='5s';
insert into eldervale_private.explore_defs(kind,id,data) select 'step',r->>'id',r-'id' from jsonb_array_elements($j$[{"id":"e_fountain_coins","tier":"easy","type":"dig","x":-238,"z":130,"text":"Where Birchford throws its wishes, the unlucky ones roll downhill. Dig where the cobbles dip, a few steps toward the setting sun."},{"id":"e_scarecrow","tier":"easy","type":"dig","x":-292,"z":136,"text":"He guards the barley with a turnip for a head and no fear at all. Dig at his feet; he will not mind."},{"id":"e_coop","tier":"easy","type":"dig","x":-279,"z":123,"text":"Seven hens, one egg, and a great deal of argument. Dig just behind the house of the arguing."},{"id":"e_map_wayfarer","tier":"easy","type":"map","x":-313,"z":-143,"text":"A torn corner of a map. A tent, a pot, a fire — and a small inked X."},{"id":"e_map_crown_fountain","tier":"easy","type":"map","x":-344,"z":-296,"text":"A sketch of a castle courtyard with a fountain drawn in blue. The X is close by the water."},{"id":"e_bearing_well","tier":"easy","type":"bearing","x":-187,"z":170,"text":"From the well of the Grand Market, walk four paces toward Emberspire and four toward the river. Dig."},{"id":"e_wave_pier","tier":"easy","type":"emote","x":300,"z":362,"emote":"wave","text":"Gulls overhead, salt in the air: at the start of the long walk over the water, wave to the boats."},{"id":"e_bow_statues","tier":"easy","type":"emote","x":-232,"z":168,"emote":"bow","text":"Between a king and a queen of stone, show some respect."},{"id":"e_dance_tam","tier":"easy","type":"emote","x":-333,"z":-4,"emote":"dance","text":"By a hut that will fall down any year now, dance — gently."},{"id":"e_talk_corin","tier":"easy","type":"talk","npc":"8e1013ae-c555-4aff-a4ba-8425fb7a290a","npcName":"Corin the Lamplighter","text":"I keep the dark at bay in Birchford, one wick at a time. Ask me what burns green.","reply":"“Green? That is the candle-stewards’ fault, not my oil. Here — someone left this with me for whoever asked.”"},{"id":"e_talk_tam","tier":"easy","type":"talk","npc":"9a3750ac-1129-4832-8c0a-cf7cc5c048ce","npcName":"Old Tam the Fisherman","text":"Forty years of “about to fall down” and still he fishes. Ask him for the line.","reply":"“The line? Ha. Riddle-folk. Fine — this was tangled in my net last spring.”"},{"id":"e_talk_alden","tier":"easy","type":"talk","npc":"9648060c-eafe-4da9-8c43-d7c40c47e836","npcName":"Alden the Wayfarer","text":"He has walked every road and still prefers the one with a campfire on it.","reply":"“Ah, a riddle-walker. The last one left this by the pot and never came back for it.”"},{"id":"e_crate_wayfarer","tier":"easy","type":"crate","crate":"wayfarer_supplies","text":"Rations, rope and a riddle: search the crate the wayfarers share."},{"id":"e_crate_tam","tier":"easy","type":"crate","crate":"old_tam_tackle","text":"Hooks and floats and something folded small: search the old fisher’s tackle."},{"id":"e_crate_gate","tier":"easy","type":"crate","crate":"castle_gate_stores","text":"The gate of every road keeps its stores close. Search them."},{"id":"e_milestone","tier":"easy","type":"dig","x":-232,"z":-188,"text":"“Too far,” someone scratched. Dig three steps from the stone that counts the leagues."},{"id":"m_moonmere_shrine","tier":"medium","type":"dig","x":-78,"z":101,"text":"Where fishers leave a painted stone for the one under the water, dig behind the offerings."},{"id":"m_heron_tally","tier":"medium","type":"dig","x":145,"z":346,"text":"A heron counts the clumsy. Dig where the counted would have climbed out."},{"id":"m_cairn","tier":"medium","type":"dig","x":-57,"z":-117,"text":"“Here lies no one. We built it in case.” Dig beside the case."},{"id":"m_map_winterwatch","tier":"medium","type":"map","x":224,"z":-238,"text":"A map scrap drawn in a cold hand: a square, a fountain, four lamps. The X is on the side of the rising sun."},{"id":"m_map_emberspire","tier":"medium","type":"map","x":252,"z":218,"text":"Kiln-smoke drawn in charcoal, a round square and a fountain. The X sits toward the market."},{"id":"m_map_silverfin","tier":"medium","type":"map","x":160,"z":104,"text":"Blue ink, a great lake, a wet journal sketched on the shore. X marks the south bank."},{"id":"m_bearing_kiln","tier":"medium","type":"bearing","x":239,"z":200,"text":"From the first Emberwright’s statue, five paces toward the castle and three toward the frost. Dig."},{"id":"m_bearing_frost","tier":"medium","type":"bearing","x":205,"z":-256,"text":"Stand at the cracked tablet that counts the winters. Four paces west, four south. Dig."},{"id":"m_think_founding","tier":"medium","type":"emote","x":-241,"z":124,"emote":"think","text":"Where a stake was driven because the fish were stupid, consider whether the fish have learned."},{"id":"m_cheer_ember","tier":"medium","type":"emote","x":257,"z":209,"emote":"cheer","text":"In the warmest square in Eldervale, beside water that never freezes, cheer."},{"id":"m_kneel_frostfang","tier":"medium","type":"emote","x":62,"z":-247,"emote":"kneel","text":"Kneel where the wolves came to a burial and did not howl."},{"id":"m_talk_wenna","tier":"medium","type":"talk","npc":"96c070e2-a084-4db7-2499-9badcaca15e6","npcName":"Wenna Saltglass","text":"She mends the nets and knows the tides. Ask her which way the bell rings.","reply":"“Under the water, love. Always under the water. Take this; it washed up with the kelp.”"},{"id":"m_talk_wwcook","tier":"medium","type":"talk","npc":"529b34ed-e8b2-4735-9fca-463f3d39ec9f","npcName":"Winterwatch Cook","text":"The warmest pot on the frontier. Ask the one who stirs it.","reply":"“A riddle? In my kitchen? Fine. It was in the flour sack. Do not ask how.”"},{"id":"m_talk_emsmith","tier":"medium","type":"talk","npc":"efa05eb5-aea8-4164-a784-d39beee8ef3f","npcName":"Emberspire Smith","text":"Hammer and kiln-heat: ask the one who owes a debt to the fire.","reply":"“Every smith here owes the fire. This was under my anvil this morning.”"},{"id":"m_talk_ottilie","tier":"medium","type":"talk","npc":"2440a89d-bdff-4082-8a60-325865a2bffc","npcName":"Ottilie the Chandler","text":"She sells what the lamplighter burns and the stewards distrust. Ask her about wax.","reply":"“Wax, wax, always wax. Here — sealed with my own, at someone’s request.”"},{"id":"m_crate_loft","tier":"medium","type":"crate","crate":"saltglass_loft","text":"Where nets dry and gulls steal, search the loft’s crate."},{"id":"m_crate_ww","tier":"medium","type":"crate","crate":"winterwatch_market","text":"A frontier market keeps its spare stock in a crate. Search it."},{"id":"m_crate_em","tier":"medium","type":"crate","crate":"emberspire_market","text":"Warm bricks, warm bread and a warm crate by the market. Search it."},{"id":"h_veil_ledge","tier":"hard","type":"dig","x":30,"z":-28,"text":"Behind the falls, above the pool, where only the sure-footed stand: dig.","area":"veilfall_grotto"},{"id":"h_grove_heart","tier":"hard","type":"dig","x":38,"z":-22,"text":"Where moths weave what they will never finish, dig beside the shrine.","area":"thornveil_grove"},{"id":"h_runebound","tier":"hard","type":"dig","x":-27,"z":-297,"text":"The ruins guard something. Dig where its warning stands."},{"id":"h_corrow","tier":"hard","type":"dig","x":203,"z":388,"text":"A mayor who never left lies by the dunes. Dig where he would have planted his feet."},{"id":"h_map_isle","tier":"hard","type":"map","x":38,"z":-6,"text":"A sea-chart of a small island with a broken lighthouse. X marks the dunes in the middle.","area":"gullwing_isle"},{"id":"h_map_plateau","tier":"hard","type":"map","x":46,"z":-12,"text":"A climber’s sketch: a high meadow, a tarn, a cairn. X on the tarn’s south shore.","area":"stormcrown_plateau"},{"id":"h_bearing_cairn","tier":"hard","type":"bearing","x":57,"z":24,"text":"At the storm-cairn that lightning will not touch, three paces west and four south. Dig.","area":"stormcrown_plateau"},{"id":"h_bow_lamp","tier":"hard","type":"emote","x":44,"z":0,"emote":"bow","text":"Before the lamp that was never theirs to keep alight, bow.","area":"quiet_lamp_shrine"},{"id":"h_clap_lighthouse","tier":"hard","type":"emote","x":58,"z":-20,"emote":"clap","text":"Where the keeper let the lamp go out on purpose, applaud the decision.","area":"gullwing_isle"},{"id":"h_shrug_runebound","tier":"hard","type":"emote","x":-30,"z":-303,"emote":"shrug","text":"Before a stone that says the ruins guard something, admit you do not know what."},{"id":"h_talk_orrin","tier":"hard","type":"talk","npc":"cbb796a6-29c3-45cb-8bba-2774aa21189f","npcName":"Orrin the Storykeeper","text":"He keeps every tale on the Kingsroad. Ask him for the one about the riddle-folk.","reply":"“Ah, that tale ends with you, I think. Here is its last page.”"},{"id":"h_talk_saffi","tier":"hard","type":"talk","npc":"863251ea-c761-49d6-8e2e-d8a73d724d21","npcName":"Saffi the Gem Trader","text":"She weighs every stone twice. Ask her about the pearl behind the falls.","reply":"“A Veilfall pearl? If I had one I would not be talking to you. I have this instead.”"},{"id":"h_crate_cove","tier":"hard","type":"crate","crate":"cove_stash","text":"The smugglers keep their stash where the tide cannot reach. Search it."},{"id":"h_crate_wreck","tier":"hard","type":"crate","crate":"isle_wreck","text":"A sloop ran aground with no lamp lit. Search what it was carrying."}]$j$::jsonb) r
 on conflict(kind,id) do update set data=excluded.data,updated_at=now() where not eldervale_private.explore_defs.owner_edited and eldervale_private.explore_defs.data is distinct from excluded.data;
