ht":7},{"item":"runiteBar","min":1,"max":2,"weight":5},{"item":"adamantBar","min":2,"max":4,"weight":6},{"item":"tidesteelArrows","min":20,"max":60,"weight":6},{"item":"windstepBrew","min":1,"max":2,"weight":5},{"item":"serpentbaneTonic","min":1,"max":2,"weight":4},{"item":"cutGem","min":2,"max":4,"weight":6},{"item":"deepglowAngler","min":2,"max":4,"weight":4},{"item":"keepsakeHourglass","min":1,"max":1,"weight":2},{"item":"keepsakeStarchart","min":1,"max":1,"weight":2},{"item":"keepsakeBrooch","min":1,"max":1,"weight":2}]},{"id":"rare","rows":[{"item":"keepsakeCirclet","min":1,"max":1,"weight":1},{"item":"keepsakeWandererLantern","min":1,"max":1,"weight":1},{"item":"keepsakeTidePin","min":1,"max":1,"weight":1}]}]$j$::jsonb) r
 on conflict(kind,id) do update set data=excluded.data,updated_at=now() where not eldervale_private.explore_defs.owner_edited and eldervale_private.explore_defs.data is distinct from excluded.data;
